# Expected values are SymPy's outputs for the same calls (sympy/integrals/tests/test_quadrature.py);
# the rows come from the battery that compares this port with SymPy.

test_that("quadrature: gauss_chebyshev_t matches SymPy", {
  expect_identical(.pyrun(local({ .pyT(gauss_chebyshev_t(1, 17)) })), "([0], [3.1415926535897932])")
  expect_identical(.pyrun(local({ .pyT(gauss_chebyshev_t(2, 17)) })), "([0.70710678118654752, -0.70710678118654752], [1.5707963267948966, 1.5707963267948966])")
