  expect_identical(.pyrun(local({ .pyT(gauss_chebyshev_t(3, 40)) })), "([0.8660254037844386467637231707529361834714, 0, -0.8660254037844386467637231707529361834714], [1.047197551196597746154214461093167628066, 1.047197551196597746154214461093167628066, 1.047197551196597746154214461093167628066])")
